'use strict';
// Versioned migrations (PLAN P9.2, §8 item 6; CLONE_SPEC.md §39.3), real server + SQLite files:
//   • every schema fixture (a database made by the server of each merged phase, tests/fixtures/schemas, generated by
//     scripts/make-schema-fixtures.js with invented data) upgrades in place with this build: migrations 0001 baseline and
//     0002 operations are recorded with checksums, the data survive (accounts, trades, audit rows), and the integrity,
//     ledger / journal, Perps journal and audit-chain verifiers pass; a restart applies nothing more;
//   • a fresh database ends at the same schema as an upgraded one (same tables and columns);
//   • a database recorded at a newer schema version is refused at start, as is one whose applied migration was edited
//     (checksum), and a held migration lock refuses a second runner;
//   • a failing migration rolls back completely.
const { test, after } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const zlib = require('node:zlib');
const { DatabaseSync } = require('node:sqlite');
const { FIXTURE_KEY, PHASES } = require('../scripts/make-schema-fixtures');

process.env.SECRET_KEY = FIXTURE_KEY; // the public test key the fixtures' audit chains were sealed with (before any server module loads it)
const { start } = require('../server/index.js');
const migrations = require('../server/migrations');
const { verifyDatabase } = require('../server/verify');

const TMP = fs.mkdtempSync(path.join(os.tmpdir(), 'parlance-migrations-'));
const FIX = path.join(__dirname, 'fixtures', 'schemas');
const HIGH = { burst: 1e6, per_second: 1e6 };
const opts = (dbFile, extra = {}) => ({ port: 0, dbFile, quiet: true, sports: false, tickMs: 500, rate: { burst: 1e6, perSec: 1e6 }, security: { challengeMode: 'off', authRate: HIGH, writeRate: HIGH }, ...extra });
after(() => { fs.rmSync(TMP, { recursive: true, force: true }); });

function loadFixture(name) {
  const file = path.join(TMP, name, `${name}.db`);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const db = new DatabaseSync(file);
  db.exec(zlib.gunzipSync(fs.readFileSync(path.join(FIX, `${name}.sql.gz`))).toString('utf8'));
  db.exec('PRAGMA journal_mode = WAL');
  db.close();
  return file;
}
const schemaOf = (file) => {
  const d = new DatabaseSync(file);
  try {
    const out = {};
    for (const t of d.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name").all()) out[t.name] = d.prepare(`PRAGMA table_info("${t.name}")`).all().map((c) => c.name).sort().join(',');
    return out;
  } finally { d.close(); }
};

test('every released schema upgrades in place and passes the ledger, journal and audit-chain verifiers', async () => {
  const fixtures = fs.readdirSync(FIX).filter((f) => f.endsWith('.sql.gz')).map((f) => f.slice(0, -7)).sort();
  assert.deepEqual(fixtures, PHASES.map(([n]) => n).sort(), 'one fixture per merged phase (scripts/make-schema-fixtures.js)');
  for (const name of fixtures) {
    const file = loadFixture(name);
    const before = new DatabaseSync(file);
    const pre = { users: before.prepare('SELECT COUNT(*) c FROM users').get().c, trades: before.prepare('SELECT COUNT(*) c FROM trades').get().c, audit: before.prepare('SELECT COUNT(*) c FROM admin_audit').get().c,
      ada: before.prepare("SELECT balance_cents FROM users WHERE email='ada.fixture@example.test'").get().balance_cents, migrated: !!before.prepare("SELECT 1 FROM sqlite_master WHERE name='schema_migrations'").get() };
    before.close();
    assert.equal(pre.migrated, false, `${name} predates versioned migrations`);
    assert.ok(pre.audit >= 2 && pre.users >= 3, `${name} holds the invented data`);
    const srv = await start(opts(file));
    try {
      const st = migrations.status(srv.db);
      assert.equal(st.version, migrations.LATEST, `${name}: upgraded to the latest schema`);
      assert.deepEqual(st.applied.map((m) => m.name), migrations.MIGRATIONS.map((m) => m.name));
      const v = verifyDatabase(srv.db, { keyDir: path.dirname(file) });
      assert.ok(v.ok, `${name}: verifiers after the upgrade ${JSON.stringify(v.checks)}`);
      assert.equal(srv.db.prepare('SELECT COUNT(*) c FROM users').get().c >= pre.users, true);
      assert.equal(srv.db.prepare('SELECT COUNT(*) c FROM trades').get().c >= pre.trades, true, 'trades kept');
      assert.equal(srv.db.prepare("SELECT balance_cents FROM users WHERE email='ada.fixture@example.test'").get().balance_cents, pre.ada, 'balances kept');
      assert.ok(srv.db.prepare('PRAGMA table_info(sessions)').all().some((c) => c.name === 'origin_kind'), '0002 columns added');
      assert.ok(srv.db.prepare('SELECT COUNT(*) c FROM crypto_keys').get().c >= 1, 'key metadata registered');
      // The site still works on the upgraded database: a member signs in and the admin audit log appends.
      const r = await fetch(`http://127.0.0.1:${srv.port}/readyz`);
      assert.equal(r.status, 200, `${name}: ready`);
    } finally { await srv.close(); }
    // A restart applies nothing more and the checksums still match.
    const srv2 = await start(opts(file));
    try { assert.deepEqual(srv2.app.locals.migrationsApplied, []); } finally { await srv2.close(); }
  }
});

test('a fresh database ends at the same schema as an upgraded one', async () => {
  const fresh = path.join(TMP, 'fresh', 'fresh.db');
  const srv = await start(opts(fresh));
  await srv.close();
  const up = path.join(TMP, 'phase-8', 'phase-8.db');
  const a = schemaOf(fresh); const b = schemaOf(up);
  for (const [t, cols] of Object.entries(b)) if (a[t] !== undefined) assert.equal(a[t], cols, `table ${t} has the same columns fresh and upgraded`);
  for (const t of ['schema_migrations', 'ops_backups', 'ops_wal_segments', 'ops_restore_drills', 'ops_anchors', 'ops_alerts', 'ops_alert_contacts', 'ops_launch_items', 'crypto_keys']) assert.ok(a[t] && b[t], `${t} exists in both`);
});

test('refusals: a newer schema, an edited migration, a held lock; a failing migration rolls back', async () => {
  const file = path.join(TMP, 'refuse', 'r.db');
  const srv = await start(opts(file));
  await srv.close();
  // Newer: a row for a migration this build does not know.
  let d = new DatabaseSync(file);
  d.prepare('INSERT INTO schema_migrations(id,name,checksum,applied_at) VALUES(?,?,?,?)').run(migrations.LATEST + 1, 'from-the-future', 'x', new Date().toISOString());
  d.close();
  await assert.rejects(start(opts(file)), (e) => e.code === 'schema_newer' && /newer than this build knows/.test(e.message));
  d = new DatabaseSync(file);
  d.prepare('DELETE FROM schema_migrations WHERE id=?').run(migrations.LATEST + 1);
  // Edited: the recorded checksum of 0002 differs from this build's.
  d.prepare("UPDATE schema_migrations SET checksum='0000' WHERE id=2").run();
  d.close();
  await assert.rejects(start(opts(file)), (e) => e.code === 'schema_checksum' && /changed after it was applied/.test(e.message));
  d = new DatabaseSync(file);
  d.prepare('UPDATE schema_migrations SET checksum=? WHERE id=2').run(migrations.checksum(migrations.MIGRATIONS[1]));
  // Lock: a fresh lock row held by another runner refuses pending work (here: 0002 removed so it is pending again).
  d.prepare('DELETE FROM schema_migrations WHERE id=2').run();
  d.prepare('INSERT INTO schema_migrations_lock(id,holder,ts) VALUES(1,?,?)').run('pid 999999', Date.now());
  d.close();
  await assert.rejects(start(opts(file)), (e) => e.code === 'migration_locked');
  d = new DatabaseSync(file);
  d.prepare('DELETE FROM schema_migrations_lock').run();
  d.close();
  const ok = await start(opts(file));
  try { assert.deepEqual(ok.app.locals.migrationsApplied, [2], 'the pending migration runs once the lock is free'); } finally { await ok.close(); }
  // Rollback: a migration that throws half-way leaves no trace.
  const mem = new DatabaseSync(':memory:');
  mem.exec('CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT)');
  const failing = { id: 1, name: 'failing', file: __filename, up(db) { db.exec('CREATE TABLE half_done(x)'); throw new Error('boom'); } };
  const saved = migrations.MIGRATIONS.splice(0, migrations.MIGRATIONS.length, failing);
  try {
    assert.throws(() => migrations.run(mem, {}), (e) => e.code === 'migration_failed' && /rolled back/.test(e.message));
    assert.equal(mem.prepare("SELECT COUNT(*) c FROM sqlite_master WHERE name='half_done'").get().c, 0, 'rolled back');
    assert.equal(mem.prepare('SELECT COUNT(*) c FROM schema_migrations').get().c, 0);
    assert.equal(mem.prepare('SELECT COUNT(*) c FROM schema_migrations_lock').get().c, 0, 'lock released');
  } finally { migrations.MIGRATIONS.splice(0, migrations.MIGRATIONS.length, ...saved); mem.close(); }
});
